struct Coord { float U,V,SignX,SignY,Weight; int32_t X,Y; };
inline uint32_t Hash(int32_t x,int32_t y,uint32_t seed)
{
    uint32_t h=uint32_t(x)*0x8da6b343u ^ uint32_t(y)*0xd8163841u ^ seed;
    h^=h>>16; h*=0x7feb352du; h^=h>>15; h*=0x846ca68bu; h^=h>>16;
    return h;
}
inline void Coordinates(float u,float v,Coord (&c)[3])
{
    const float px=u*.72f,py=v*.72f;
    const float gx=px-py*.57735026919f,gy=py*1.15470053838f;
    const int32_t ix=int32_t(std::floor(gx)),iy=int32_t(std::floor(gy));
    const float fx=gx-float(ix),fy=gy-float(iy);
    if(fx+fy<1.f)
    {c[0]={0,0,0,0,1.f-fx-fy,ix,iy};c[1]={0,0,0,0,fx,ix+1,iy};c[2]={0,0,0,0,fy,ix,iy+1};}
    else
    {c[0]={0,0,0,0,fx+fy-1.f,ix+1,iy+1};c[1]={0,0,0,0,1.f-fx,ix,iy+1};c[2]={0,0,0,0,1.f-fy,ix+1,iy};}
    float sum=0;
    for(auto& q:c){q.Weight=std::max(0.f,q.Weight);q.Weight*=q.Weight;q.Weight*=q.Weight;sum+=q.Weight;}
    for(auto& q:c)
    {
        q.Weight/=std::max(sum,.00001f);
        const uint32_t bits=Hash(q.X,q.Y,0x967a889bu);
        q.SignX=(bits&1u)?1.f:-1.f;q.SignY=(bits&2u)?1.f:-1.f;
        q.U=u*q.SignX+float(Hash(q.X,q.Y,0x68bc21ebu)>>8)*(1.f/16777216.f);
        q.V=v*q.SignY+float(Hash(q.X,q.Y,0x02e5be93u)>>8)*(1.f/16777216.f);
    }
}
inline float Bilinear(float u,float v)
{
    // Texture texel centres, including repeat across negative/wrapped UVs.
    const float x=(u-std::floor(u))*Size-.5f,y=(v-std::floor(v))*Size-.5f;
    const int32_t ix=int32_t(std::floor(x)),iy=int32_t(std::floor(y));
    const float fx=x-float(ix),fy=y-float(iy);
    const int32_t x0=uint32_t(ix)&(Size-1),x1=(x0+1)&(Size-1);
    const int32_t y0=uint32_t(iy)&(Size-1),y1=(y0+1)&(Size-1);
    const float a=float(Samples[y0*Size+x0])*(1.f/65535.f),b=float(Samples[y0*Size+x1])*(1.f/65535.f);
    const float c=float(Samples[y1*Size+x0])*(1.f/65535.f),d=float(Samples[y1*Size+x1])*(1.f/65535.f);
    return (a+(b-a)*fx)+((c+(d-c)*fx)-(a+(b-a)*fx))*fy;
}
inline float Height(float worldX,float worldY)
{
    Coord c[3];Coordinates(worldX/145.f*.52f,worldY/145.f*.52f,c);
    float h[3],support[3],w[3];float peak=-1.f;
    for(int i=0;i<3;++i){h[i]=Bilinear(c[i].U,c[i].V);support[i]=c[i].Weight+.24f*h[i];peak=std::max(peak,support[i]);}
    const float cut=peak-.32f;float sum=0,value=0;
    for(int i=0;i<3;++i){w[i]=std::max(0.f,support[i]-cut)*c[i].Weight;sum+=w[i];value+=w[i]*h[i];}
    return value/std::max(sum,.0001f);
}
inline float Displacement(float worldX,float worldY)
{
    const float normalized=(Height(worldX,worldY)-HeightLow)/std::max(.0001f,HeightHigh-HeightLow);
    return (std::clamp(normalized,0.f,1.f)-.5f)*ReliefRangeCm;
}
